// Kiểm tra đầu vào theo DANH SÁCH CHO PHÉP (cái gì hợp lệ), không phải danh sách cấm
function validateUser(body) {
  const errors = {};
  if (typeof body.email !== "string" || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(body.email)) errors.email = "email sai";
  if (!Number.isInteger(body.age) || body.age < 13 || body.age > 120) errors.age = "tuổi sai";
  if (!["user", "editor"].includes(body.role ?? "user")) errors.role = "vai trò sai";   // KHÔNG cho tự đặt "admin"
  return errors;
}

console.log(JSON.stringify(validateUser({ email: "a@x.vn", age: 20 })));
console.log(JSON.stringify(validateUser({ email: "oops", age: "20", role: "admin" })));

