solution.code:
function pick(obj, allowed) {
  return Object.fromEntries(Object.entries(obj).filter(([k]) => allowed.includes(k)));
}
console.log(JSON.stringify(pick({ name: "An", role: "admin", isPaid: true }, ["name"])));

